          item.linkedId && item.linkedType === "Location"
            ? `location:${item.linkedId}`
            : "",
          item.linkedId && item.linkedType === "Vendor"
            ? `vendor:${item.linkedId}`
            : "",
          item.linkedId && item.linkedType === "Work Order"
